setup.text:
import json, os, socket, sys
kind, where, replyf, ready = sys.argv[1:5]
log = os.environ.get('DIFFTEST_FAKELOG')
raw = open(replyf, 'rb').read() if os.path.exists(replyf) else None


def note(s):
    if log:
        with open(log, 'a') as f:
            f.write(s + '\n')


if kind == 'unix':
    srv = socket.socket(socket.AF_UNIX)
    srv.bind(where)
    srv.listen(5)
    open(ready, 'w').write('1')
    while True:
        c, _ = srv.accept()
        buf = b''
        while not buf.endswith(b'\n'):
            d = c.recv(65536)
            if not d:
                break
            buf += d
        try:
            note('host-sock ' + json.dumps(json.loads(buf.decode()), sort_keys=True))
        except Exception:
            note('host-sock (not json)')
        if raw is not None:
            c.sendall(raw)
        c.close()
else:
    srv = socket.socket()
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind(('127.0.0.1', 0))
    srv.listen(5)
    open(ready, 'w').write(str(srv.getsockname()[1]))
    while True:
        c, _ = srv.accept()
        head = b''
        while b'\r\n\r\n' not in head:
            d = c.recv(65536)
            if not d:
                break
            head += d
        if not head:
            c.close()
            continue
        h, _, body = head.partition(b'\r\n\r\n')
        lines = h.decode().split('\r\n')
        hdr = {l.split(':', 1)[0].lower(): l.split(':', 1)[1].strip() for l in lines[1:] if ':' in l}
        n = int(hdr.get('content-length', '0'))
        while len(body) < n:
            body += c.recv(65536)
        try:
            shown = json.dumps(json.loads(body), sort_keys=True)
        except Exception:
            shown = '(not json)'
        note('host-http %s auth=%s type=%s body=%s' % (lines[0].split(' HTTP')[0], hdr.get('authorization'), hdr.get('content-type'), shown))
        status, _, payload = (raw or b'500\n').partition(b'\n')
        c.sendall(b'HTTP/1.0 ' + status + b' X\r\nContent-Type: application/json\r\nContent-Length: ' + str(len(payload)).encode() + b'\r\n\r\n' + payload)
        c.close()

